    question: "FREE SEMINAR\nTopic: Introduction to Personal Finance\nDate: Saturday, September 7\nTime: 2:00 PM – 4:00 PM\nVenue: Community Center, Room 5\nRegistration required. Call 555-0190 to reserve your spot.\n\nQ: How can people register for the seminar?",
